<?php
namespace App\Controllers;
use App\Core\{Session,Database,View,Request,Csrf,Response};
final class PortalController {public function login():void{View::render('portal/login',['error'=>Session::pullFlash('error')]);}public function authenticate():void{$r=new Request;if(!Csrf::check($r->input('_csrf'))){Session::flash('error','Security token expired.');Response::redirect(route('portal.login'));}$s=Database::pdo()->prepare('SELECT * FROM portal_users WHERE username=? AND is_active=1');$s->execute([$r->input('username')]);$u=$s->fetch();if(!$u||!password_verify((string)$r->input('password'),$u['password_hash'])){Session::flash('error','Invalid portal login.');Response::redirect(route('portal.login'));}Session::put('portal_user_id',(int)$u['id']);Response::redirect(route('portal.home'));}public function index():void{if(!Session::get('portal_user_id'))Response::redirect(route('portal.login'));View::render('portal/index');}public function logout():void{Session::forget('portal_user_id');Response::redirect(route('portal.login'));}}
